import type { JSX } from "preact";
import type { Status } from "../../api/types";
import { t } from "../../i18n/pt-BR";
import { fullDate, shortNumber } from "../../lib/format";
import { Icon } from "../ui/Icon";

export type ToggleKind = "boost" | "fav" | "bookmark";

interface StatusActionsBarProps {
  target: Status;
  canAct: boolean;
  /** Self-authored status shown from its own instance (edit button). */
  showEdit: boolean;
  /** Self-authored status while authenticated (delete button). */
  showDelete: boolean;
  /** Someone else's status while authenticated (more/⋯ menu). */
  showMore: boolean;
  /** Status can be boosted (or is already boosted and can be undone). */
  showBoost: boolean;
  /** Quoting is supported and allowed for this status. */
  showQuote: boolean;
  /** Own pinnable status (pin button). */
  showPin: boolean;
  pinned: boolean;
  menuOpen: boolean;
  onReply: (e: MouseEvent) => void;
  onQuote: (e: MouseEvent) => void;
  onAct: (kind: ToggleKind, e: MouseEvent) => void;
  onEdit: (e: MouseEvent) => void;
  onDelete: (e: MouseEvent) => void;
  onShare: (e: MouseEvent) => void;
  onMore: (e: MouseEvent) => void;
  onPin: (e: MouseEvent) => void;
}

/** Reply / boost / fav / bookmark bar plus edit, delete and more-menu triggers. */
export function StatusActionsBar({
  target,
  canAct,
  showEdit,
  showDelete,
  showMore,
  showBoost,
  showQuote,
  showPin,
  pinned,
  menuOpen,
  onReply,
  onQuote,
  onAct,
  onEdit,
  onDelete,
  onShare,
  onMore,
  onPin,
}: StatusActionsBarProps): JSX.Element {
  return (
    <div class="actions" onClick={(e) => e.stopPropagation()}>
      <button
        type="button"
        class="status-action reply"
        title={t.reply}
        aria-label={target.repliesCount > 0 ? `${t.reply} (${target.repliesCount})` : t.reply}
        onClick={onReply}
        disabled={!canAct}
      >
        <Icon name="share-forward-line" size={16} class="rot-180" />
        {target.repliesCount > 0 && <span class="count">{shortNumber(target.repliesCount)}</span>}
      </button>
      {showQuote && (
        <button
          type="button"
          class="status-action quote"
          title={t.quote}
          aria-label={target.quotesCount > 0 ? `${t.quote} (${target.quotesCount})` : t.quote}
          onClick={onQuote}
          disabled={!canAct}
        >
          <Icon name="quote-left-line" size={16} />
          {target.quotesCount > 0 && <span class="count">{shortNumber(target.quotesCount)}</span>}
        </button>
      )}
      {showBoost && (
        <button
          type="button"
          class={`status-action boost ${target.reblogged ? "on" : ""}`}
          title={t.boost}
          aria-label={target.reblogsCount > 0 ? `${t.boost} (${target.reblogsCount})` : t.boost}
          aria-pressed={!!target.reblogged}
          onClick={(e) => onAct("boost", e)}
          disabled={!canAct}
        >
          <Icon name="repeat-line" size={16} />
          {target.reblogsCount > 0 && <span class="count">{shortNumber(target.reblogsCount)}</span>}
        </button>
      )}
      <button
        type="button"
        class={`status-action fav ${target.favourited ? "on" : ""}`}
        title={t.favourite}
        aria-label={
          target.favouritesCount > 0 ? `${t.favourite} (${target.favouritesCount})` : t.favourite
        }
        aria-pressed={!!target.favourited}
        onClick={(e) => onAct("fav", e)}
        disabled={!canAct}
      >
        <Icon name={target.favourited ? "heart-fill" : "heart-line"} size={16} />
        {target.favouritesCount > 0 && (
          <span class="count">{shortNumber(target.favouritesCount)}</span>
        )}
      </button>
      <button
        type="button"
        class={`status-action bookmark ${target.bookmarked ? "on" : ""}`}
        title={t.bookmark}
        aria-label={t.bookmark}
        aria-pressed={!!target.bookmarked}
        onClick={(e) => onAct("bookmark", e)}
        disabled={!canAct}
      >
        <Icon name={target.bookmarked ? "bookmark-fill" : "bookmark-line"} size={16} />
      </button>
      <button
        type="button"
        class="status-action share"
        title={t.share}
        aria-label={t.share}
        onClick={onShare}
      >
        <Icon name="share-2-line" size={16} />
      </button>
      {showPin && (
        <button
          type="button"
          class={`status-action pin ${pinned ? "on" : ""}`}
          title={pinned ? t.unpinPost : t.pinPost}
          aria-label={pinned ? t.unpinPost : t.pinPost}
          aria-pressed={pinned}
          onClick={onPin}
        >
          <Icon name={pinned ? "pin-fill" : "pin-line"} size={16} />
        </button>
      )}
      {showEdit && (
        <button
          type="button"
          class="status-action edit"
          title={t.editPost}
          aria-label={t.editPost}
          onClick={onEdit}
        >
          <Icon name="pencil-line" size={16} />
        </button>
      )}
      {showDelete && (
        <button
          type="button"
          class="status-action delete"
          title={t.deletePost}
          aria-label={t.deletePost}
          onClick={onDelete}
        >
          <Icon name="delete-line" size={16} />
        </button>
      )}
      {showMore && (
        <div class="action-more">
          <button
            type="button"
            class={`status-action more ${menuOpen ? "on" : ""}`}
            title={t.moreOptions}
            aria-label={t.moreOptions}
            aria-haspopup="menu"
            aria-expanded={menuOpen}
            onClick={onMore}
          >
            <Icon name="more-1-line" size={16} />
          </button>
        </div>
      )}
      <div class="spacer" />
      {target.editedAt && (
        <span class="edit-badge" title={fullDate(target.editedAt)}>
          <Icon name="history-line" size={13} />
          {t.edited}
        </span>
      )}
    </div>
  );
}
